def lower_bound(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo


def upper_bound(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
    return lo


times = list(map(int, input().split()))
queries = list(map(int, input().split()))
for t in queries:
    first = lower_bound(times, t)
    last = upper_bound(times, t) - 1
    if first > last:
        print(f"{t}s: nobody, a new runner would place {first + 1}")
    elif first == last:
        print(f"{t}s: place {first + 1}")
    else:
        print(f"{t}s: places {first + 1} to {last + 1}")

