def days_needed(weights, capacity):
    days, load = 1, 0
    for w in weights:
        if load + w > capacity:
            days += 1
            load = 0
        load += w
    return days


def smallest_that_works(lo, hi, ok):
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo


weights = list(map(int, input().split()))
limits = list(map(int, input().split()))
for d in limits:
    cap = smallest_that_works(
        max(weights), sum(weights), lambda c: days_needed(weights, c) <= d
    )
    print(f"{d} days: capacity {cap}")

